import React, { useState, useEffect } from 'react';
import {
 // Container,
  Paper,
  Typography,
  TextField,
  Button,
  Grid,
  Box,
  ThemeProvider,
  createTheme,
  MenuItem,
  FormControl,
  InputLabel,
  Select,
  Drawer,
  List,
  ListItem,
  ListItemIcon,
  ListItemText,
  ListItemButton,
  AppBar,
  Toolbar,
  IconButton,
  CssBaseline,
  Collapse,
  ToggleButton,
  ToggleButtonGroup,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  ButtonGroup,
} from '@mui/material';
import { DataGrid, GridColDef } from '@mui/x-data-grid';
import { format } from 'date-fns';
import PaymentIcon from '@mui/icons-material/Payment';
import StorageIcon from '@mui/icons-material/Storage';
import AssessmentIcon from '@mui/icons-material/Assessment';
import MenuIcon from '@mui/icons-material/Menu';
import PersonIcon from '@mui/icons-material/Person';
import WorkIcon from '@mui/icons-material/Work';
import BusinessIcon from '@mui/icons-material/Business';
import ExpandLess from '@mui/icons-material/ExpandLess';
import ExpandMore from '@mui/icons-material/ExpandMore';
import DownloadIcon from '@mui/icons-material/Download';
import * as XLSX from 'xlsx';
//import { saveAs } from 'file-saver';
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  PieChart,
  Pie,
  Cell,
  LineChart,
  Line,
} from 'recharts';

declare global {
  interface Window {
    showSaveFilePicker?: (options: any) => Promise<FileSystemFileHandle>;
  }
  interface FileSystemFileHandle {
   // createWritable: () => Promise<FileSystemWritableFileStream>;
  }
  interface FileSystemWritableFileStream {
  //  write: (data: any) => Promise<void>;
    close: () => Promise<void>;
  }
}

interface CRMRecord {
  id: number;
  timestamp: string;
  accountNumber: string;
  customerName: string;
  ptpAmount: number;
  status: string;
  paymentDate: string;
  contactNumber: string;
  callerName: string;
  amAndTl: string;
  process: string;
}

interface EmployeeRecord {
  id: number;
  empId: string;
  employeeName: string;
  designation: string;
  reportingManager: string;
  process: string;
  doj: string;
  experience: number;
  salary: number;
  target: number;
}

interface Designation {
  id: number;
  designationId: string;
  designationName: string;
  department: string;
  description: string;
}

const drawerWidth = 240;

const theme = createTheme({
  palette: {
    primary: {
      main: '#1976d2',
    },
    secondary: {
      main: '#dc004e',
    },
  },
});

const statusOptions = ['PTP', 'PDC', 'COLLECTED'];
const processOptions = ['BOB-W.OFF', 'ASREC', 'DMI', 'KOTAK-W.OFF', 'BOB NEW W.OFF'];

//const menuItems = [
  //{ text: 'Payment Tracker', icon: <PaymentIcon /> },
 // { text: 'Static Data', icon: <StorageIcon /> },
 // { text: 'Reports', icon: <AssessmentIcon /> },
//];

const CHART_COLORS = ['#0088FE', '#00C49F', '#FFBB28', '#FF8042', '#8884d8', '#82ca9d'];

const App: React.FC = () => {
  const [records, setRecords] = useState<CRMRecord[]>([]);
  const [employeeRecords, setEmployeeRecords] = useState<EmployeeRecord[]>([]);
  const [designations, setDesignations] = useState<Designation[]>([]);
  const [designationFormData, setDesignationFormData] = useState<Partial<Designation>>({});
  const [employeeFormData, setEmployeeFormData] = useState<Partial<EmployeeRecord>>({});
  const [formData, setFormData] = useState<Partial<CRMRecord>>({});
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [mobileOpen, setMobileOpen] = useState(false);
  const [selectedMenu, setSelectedMenu] = useState('Payment Tracker');
  const [staticDataOpen, setStaticDataOpen] = useState(false);
  const [selectedSubMenu, setSelectedSubMenu] = useState('');
  const [chartType, setChartType] = useState<'process' | 'status' | 'date'>('process');
  const [chartView, setChartView] = useState<'bar' | 'pie' | 'line'>('bar');

  const handleDrawerToggle = () => {
    setMobileOpen(!mobileOpen);
  };

  useEffect(() => {
    const loadData = async () => {
      try {
        console.log('Fetching CSV data...');
        const response = await fetch('/CRM_Ver2.csv');
        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
        const data = await response.text();
        console.log('CSV data received, processing...');
        
        const rows = data.split('\n')
          .filter(line => line.trim())
          .slice(1)
          .map((row, index) => {
            const [
              timestamp,
              accountNumber,
              customerName,
              ptpAmount,
              status,
              paymentDate,
              contactNumber,
              callerName,
              amAndTl,
              process,
            ] = row.split(',').map(field => field.trim());

            return {
              id: index + 1,
              timestamp,
              accountNumber,
              customerName,
              ptpAmount: Number(ptpAmount) || 0,
              status,
              paymentDate,
              contactNumber,
              callerName,
              amAndTl,
              process,
            };
          });
        
        console.log(`Processed ${rows.length} records`);
        setRecords(rows);
        setError(null);
      } catch (err) {
        console.error('Error loading data:', err);
        setError(err instanceof Error ? err.message : 'Failed to load data');
      } finally {
        setLoading(false);
      }
    };

    loadData();
  }, []);

  useEffect(() => {
    const loadEmployeeData = async () => {
      try {
        console.log('Fetching employee data...');
        const response = await fetch('/employee_Details.csv');
        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
        const data = await response.text();
        console.log('Employee data received, processing...');
        
        const rows = data.split('\n')
          .filter(line => line.trim())
          .slice(1)
          .map((row, index) => {
            const [
              empId,
              employeeName,
              designation,
              reportingManager,
              process,
              doj,
              experience,
              salary,
              target,
            ] = row.split(',').map(field => field.trim());

            return {
              id: index + 1,
              empId,
              employeeName,
              designation,
              reportingManager,
              process,
              doj,
              experience: Number(experience) || 0,
              salary: Number(salary) || 0,
              target: Number(target) || 0,
            };
          });
        
        console.log(`Processed ${rows.length} employee records`);
        setEmployeeRecords(rows);
      } catch (err) {
        console.error('Error loading employee data:', err);
        setError(err instanceof Error ? err.message : 'Failed to load employee data');
      }
    };

    loadEmployeeData();
  }, []);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value,
    }));
  };

  const handleSelectChange = (e: any) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value,
    }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newRecord = {
      id: records.length + 1,
      ...formData,
      timestamp: format(new Date(), 'MM/dd/yyyy HH:mm:ss'),
    } as CRMRecord;
    setRecords(prev => [...prev, newRecord]);
    setFormData({});
  };

  const handleEmployeeInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setEmployeeFormData(prev => ({
      ...prev,
      [name]: value,
    }));
  };

  const handleEmployeeSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newEmployee = {
      id: employeeRecords.length + 1,
      ...employeeFormData,
    } as EmployeeRecord;
    setEmployeeRecords(prev => [...prev, newEmployee]);
    setEmployeeFormData({});
  };

  const handleDesignationInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setDesignationFormData(prev => ({
      ...prev,
      [name]: value,
    }));
  };

  const handleDesignationSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newDesignation = {
      id: designations.length + 1,
      ...designationFormData,
    } as Designation;
    setDesignations(prev => [...prev, newDesignation]);
    setDesignationFormData({});
  };

  const handleStaticDataClick = () => {
    setStaticDataOpen(!staticDataOpen);
    setSelectedMenu('Static Data');
  };

  const handleSubMenuClick = (subMenu: string) => {
    setSelectedSubMenu(subMenu);
    setSelectedMenu('Static Data');
  };

  const columns: GridColDef[] = [
    { field: 'timestamp', headerName: 'Timestamp', width: 180 },
    { field: 'accountNumber', headerName: 'Account Number', width: 180 },
    { field: 'customerName', headerName: 'Customer Name', width: 200 },
    { field: 'ptpAmount', headerName: 'PTP Amount', width: 130, type: 'number' },
    { field: 'status', headerName: 'Status', width: 130 },
    { field: 'paymentDate', headerName: 'Payment Date', width: 130 },
    { field: 'contactNumber', headerName: 'Contact Number', width: 150 },
    { field: 'callerName', headerName: 'Caller Name', width: 150 },
    { field: 'amAndTl', headerName: 'AM & TL', width: 150 },
    { field: 'process', headerName: 'Process', width: 150 },
  ];

  const employeeColumns: GridColDef[] = [
    { field: 'empId', headerName: 'Employee ID', width: 120 },
    { field: 'employeeName', headerName: 'Employee Name', width: 180 },
    { field: 'designation', headerName: 'Designation', width: 150 },
    { field: 'reportingManager', headerName: 'Reporting Manager', width: 180 },
    { field: 'process', headerName: 'Process', width: 130 },
    { field: 'doj', headerName: 'Date of Joining', width: 130 },
    { field: 'experience', headerName: 'Experience', width: 100, type: 'number' },
    { field: 'salary', headerName: 'Salary', width: 100, type: 'number' },
    { field: 'target', headerName: 'Target', width: 100, type: 'number' },
  ];

  const designationColumns: GridColDef[] = [
    { field: 'designationId', headerName: 'Designation ID', width: 130 },
    { field: 'designationName', headerName: 'Designation Name', width: 200 },
    { field: 'department', headerName: 'Department', width: 150 },
    { field: 'description', headerName: 'Description', width: 300 },
  ];

  const drawer = (
    <div>
      <Toolbar />
      <List>
        <ListItem disablePadding>
          <ListItemButton
            selected={selectedMenu === 'Payment Tracker'}
            onClick={() => {
              setSelectedMenu('Payment Tracker');
              setSelectedSubMenu('');
            }}
          >
            <ListItemIcon><PaymentIcon /></ListItemIcon>
            <ListItemText primary="Payment Tracker" />
          </ListItemButton>
        </ListItem>

        <ListItem disablePadding>
          <ListItemButton onClick={handleStaticDataClick}>
            <ListItemIcon><StorageIcon /></ListItemIcon>
            <ListItemText primary="Static Data" />
            {staticDataOpen ? <ExpandLess /> : <ExpandMore />}
          </ListItemButton>
        </ListItem>

        <Collapse in={staticDataOpen} timeout="auto" unmountOnExit>
          <List component="div" disablePadding>
            <ListItemButton
              sx={{ pl: 4 }}
              selected={selectedSubMenu === 'Employee Record'}
              onClick={() => handleSubMenuClick('Employee Record')}
            >
              <ListItemIcon><PersonIcon /></ListItemIcon>
              <ListItemText primary="Employee Record" />
            </ListItemButton>

            <ListItemButton
              sx={{ pl: 4 }}
              selected={selectedSubMenu === 'Designation'}
              onClick={() => handleSubMenuClick('Designation')}
            >
              <ListItemIcon><WorkIcon /></ListItemIcon>
              <ListItemText primary="Designation" />
            </ListItemButton>

            <ListItemButton
              sx={{ pl: 4 }}
              selected={selectedSubMenu === 'Process Details'}
              onClick={() => handleSubMenuClick('Process Details')}
            >
              <ListItemIcon><BusinessIcon /></ListItemIcon>
              <ListItemText primary="Process Details" />
            </ListItemButton>
          </List>
        </Collapse>

        <ListItem disablePadding>
          <ListItemButton
            selected={selectedMenu === 'Reports'}
            onClick={() => {
              setSelectedMenu('Reports');
              setSelectedSubMenu('');
            }}
          >
            <ListItemIcon><AssessmentIcon /></ListItemIcon>
            <ListItemText primary="Reports" />
          </ListItemButton>
        </ListItem>
      </List>
    </div>
  );

  const renderStaticDataContent = () => {
    switch (selectedSubMenu) {
      case 'Employee Record':
        return (
          <>
            <Paper sx={{ p: 3, mb: 3 }}>
              <Typography variant="h6" gutterBottom>Add Employee Record</Typography>
              <form onSubmit={handleEmployeeSubmit}>
                <Grid container spacing={2}>
                  <Grid item xs={12} sm={6} md={4}>
                    <TextField
                      required
                      fullWidth
                      label="Employee ID"
                      name="empId"
                      value={employeeFormData.empId || ''}
                      onChange={handleEmployeeInputChange}
                    />
                  </Grid>
                  <Grid item xs={12} sm={6} md={4}>
                    <TextField
                      required
                      fullWidth
                      label="Employee Name"
                      name="employeeName"
                      value={employeeFormData.employeeName || ''}
                      onChange={handleEmployeeInputChange}
                    />
                  </Grid>
                  <Grid item xs={12} sm={6} md={4}>
                    <TextField
                      required
                      fullWidth
                      label="Designation"
                      name="designation"
                      value={employeeFormData.designation || ''}
                      onChange={handleEmployeeInputChange}
                    />
                  </Grid>
                  <Grid item xs={12} sm={6} md={4}>
                    <TextField
                      required
                      fullWidth
                      label="Reporting Manager"
                      name="reportingManager"
                      value={employeeFormData.reportingManager || ''}
                      onChange={handleEmployeeInputChange}
                    />
                  </Grid>
                  <Grid item xs={12} sm={6} md={4}>
                    <TextField
                      fullWidth
                      label="Process"
                      name="process"
                      value={employeeFormData.process || ''}
                      onChange={handleEmployeeInputChange}
                    />
                  </Grid>
                  <Grid item xs={12} sm={6} md={4}>
                    <TextField
                      required
                      fullWidth
                      label="Date of Joining"
                      name="doj"
                      type="date"
                      value={employeeFormData.doj || ''}
                      onChange={handleEmployeeInputChange}
                      InputLabelProps={{ shrink: true }}
                    />
                  </Grid>
                  <Grid item xs={12} sm={6} md={4}>
                    <TextField
                      required
                      fullWidth
                      label="Experience (Years)"
                      name="experience"
                      type="number"
                      value={employeeFormData.experience || ''}
                      onChange={handleEmployeeInputChange}
                    />
                  </Grid>
                  <Grid item xs={12} sm={6} md={4}>
                    <TextField
                      required
                      fullWidth
                      label="Salary"
                      name="salary"
                      type="number"
                      value={employeeFormData.salary || ''}
                      onChange={handleEmployeeInputChange}
                    />
                  </Grid>
                  <Grid item xs={12} sm={6} md={4}>
                    <TextField
                      required
                      fullWidth
                      label="Target"
                      name="target"
                      type="number"
                      value={employeeFormData.target || ''}
                      onChange={handleEmployeeInputChange}
                    />
                  </Grid>
                  <Grid item xs={12}>
                    <Box sx={{ display: 'flex', justifyContent: 'flex-end', mt: 2 }}>
                      <Button
                        type="submit"
                        variant="contained"
                        color="primary"
                        size="large"
                      >
                        Add Employee
                      </Button>
                    </Box>
                  </Grid>
                </Grid>
              </form>
            </Paper>

            <Paper sx={{ height: 600, width: '100%' }}>
              <DataGrid
                rows={employeeRecords}
                columns={employeeColumns}
                initialState={{
                  pagination: {
                    paginationModel: { pageSize: 10, page: 0 },
                  },
                }}
                pageSizeOptions={[10, 25, 50]}
                disableRowSelectionOnClick
                autoHeight
              />
            </Paper>
          </>
        );

      case 'Designation':
        return (
          <>
            <Paper sx={{ p: 3, mb: 3 }}>
              <Typography variant="h6" gutterBottom>Add Designation</Typography>
              <form onSubmit={handleDesignationSubmit}>
                <Grid container spacing={2}>
                  <Grid item xs={12} sm={6}>
                    <TextField
                      required
                      fullWidth
                      label="Designation ID"
                      name="designationId"
                      value={designationFormData.designationId || ''}
                      onChange={handleDesignationInputChange}
                    />
                  </Grid>
                  <Grid item xs={12} sm={6}>
                    <TextField
                      required
                      fullWidth
                      label="Designation Name"
                      name="designationName"
                      value={designationFormData.designationName || ''}
                      onChange={handleDesignationInputChange}
                    />
                  </Grid>
                  <Grid item xs={12} sm={6}>
                    <TextField
                      required
                      fullWidth
                      label="Department"
                      name="department"
                      value={designationFormData.department || ''}
                      onChange={handleDesignationInputChange}
                    />
                  </Grid>
                  <Grid item xs={12}>
                    <TextField
                      fullWidth
                      label="Description"
                      name="description"
                      multiline
                      rows={4}
                      value={designationFormData.description || ''}
                      onChange={handleDesignationInputChange}
                    />
                  </Grid>
                  <Grid item xs={12}>
                    <Box sx={{ display: 'flex', justifyContent: 'flex-end', mt: 2 }}>
                      <Button
                        type="submit"
                        variant="contained"
                        color="primary"
                        size="large"
                      >
                        Add Designation
                      </Button>
                    </Box>
                  </Grid>
                </Grid>
              </form>
            </Paper>

            <Paper sx={{ height: 600, width: '100%' }}>
              <DataGrid
                rows={designations}
                columns={designationColumns}
                initialState={{
                  pagination: {
                    paginationModel: { pageSize: 10, page: 0 },
                  },
                }}
                pageSizeOptions={[10, 25, 50]}
                disableRowSelectionOnClick
                autoHeight
              />
            </Paper>
          </>
        );

      case 'Process Details':
        return (
          <Paper sx={{ p: 3 }}>
            <Typography variant="h6" gutterBottom>Process Details</Typography>
            <Grid container spacing={2}>
              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  label="Process Name"
                  variant="outlined"
                />
              </Grid>
              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  label="Process Code"
                  variant="outlined"
                />
              </Grid>
              <Grid item xs={12}>
                <TextField
                  fullWidth
                  label="Process Description"
                  multiline
                  rows={4}
                  variant="outlined"
                />
              </Grid>
              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  label="Department"
                  variant="outlined"
                />
              </Grid>
              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  label="Manager"
                  variant="outlined"
                />
              </Grid>
              <Grid item xs={12}>
                <Box sx={{ display: 'flex', justifyContent: 'flex-end', mt: 2 }}>
                  <Button variant="contained" color="primary">
                    Add Process
                  </Button>
                </Box>
              </Grid>
            </Grid>
          </Paper>
        );

      default:
        return (
          <Paper sx={{ p: 3 }}>
            <Typography variant="h6">Static Data Management</Typography>
            <Typography>Please select a category from the menu.</Typography>
          </Paper>
        );
    }
  };

  const processChartData = () => {
    const processData = records.reduce((acc: any, curr) => {
      const process = curr.process || 'Unassigned';
      if (!acc[process]) {
        acc[process] = {
          name: process,
          count: 0,
          amount: 0,
        };
      }
      acc[process].count += 1;
      acc[process].amount += Number(curr.ptpAmount) || 0;
      return acc;
    }, {});
    return Object.values(processData);
  };

  const statusChartData = () => {
    const statusData = records.reduce((acc: any, curr) => {
      const status = curr.status || 'Pending';
      if (!acc[status]) {
        acc[status] = {
          name: status,
          count: 0,
          amount: 0,
        };
      }
      acc[status].count += 1;
      acc[status].amount += Number(curr.ptpAmount) || 0;
      return acc;
    }, {});
    return Object.values(statusData);
  };

  const dateChartData = () => {
    const dateData = records.reduce((acc: any, curr) => {
      const date = curr.paymentDate ? curr.paymentDate.split('T')[0] : 'Unscheduled';
      if (!acc[date]) {
        acc[date] = {
          name: date,
          count: 0,
          amount: 0,
        };
      }
      acc[date].count += 1;
      acc[date].amount += Number(curr.ptpAmount) || 0;
      return acc;
    }, {});
    return Object.values(dateData).sort((a: any, b: any) => a.name.localeCompare(b.name));
  };

  const getChartData = () => {
    switch (chartType) {
      case 'process':
        return processChartData();
      case 'status':
        return statusChartData();
      case 'date':
        return dateChartData();
      default:
        return [];
    }
  };

  const renderChart = () => {
    const data = getChartData();

    switch (chartView) {
      case 'bar':
        return (
          <BarChart width={800} height={400} data={data} margin={{ top: 20, right: 30, left: 20, bottom: 5 }}>
            <CartesianGrid strokeDasharray="3 3" />
            <XAxis dataKey="name" />
            <YAxis yAxisId="left" orientation="left" stroke="#8884d8" />
            <YAxis yAxisId="right" orientation="right" stroke="#82ca9d" />
            <Tooltip />
            <Legend />
            <Bar yAxisId="left" dataKey="count" fill="#8884d8" name="Count" />
            <Bar yAxisId="right" dataKey="amount" fill="#82ca9d" name="Amount" />
          </BarChart>
        );

      case 'pie':
        return (
          <PieChart width={800} height={400}>
            <Pie
              data={data}
              cx={400}
              cy={200}
              labelLine={false}
              label={({ name, percent }) => `${name} (${(percent * 100).toFixed(0)}%)`}
              outerRadius={160}
              fill="#8884d8"
              dataKey="amount"
            >
              {data.map((_: any, index: number) => (
                <Cell key={`cell-${index}`} fill={CHART_COLORS[index % CHART_COLORS.length]} />
              ))}
            </Pie>
            <Tooltip />
            <Legend />
          </PieChart>
        );

      case 'line':
        return (
          <LineChart width={800} height={400} data={data} margin={{ top: 20, right: 30, left: 20, bottom: 5 }}>
            <CartesianGrid strokeDasharray="3 3" />
            <XAxis dataKey="name" />
            <YAxis yAxisId="left" orientation="left" stroke="#8884d8" />
            <YAxis yAxisId="right" orientation="right" stroke="#82ca9d" />
            <Tooltip />
            <Legend />
            <Line yAxisId="left" type="monotone" dataKey="count" stroke="#8884d8" name="Count" />
            <Line yAxisId="right" type="monotone" dataKey="amount" stroke="#82ca9d" name="Amount" />
          </LineChart>
        );

      default:
        return null;
    }
  };

  const generateCollectionReport = () => {
    // Process-wise collection
    const processCollection = records.reduce((acc: any, curr) => {
      const process = curr.process || 'Unassigned';
      if (!acc[process]) {
        acc[process] = {
          totalAmount: 0,
          count: 0,
          collected: 0,
          pending: 0,
        };
      }
      acc[process].count += 1;
      acc[process].totalAmount += Number(curr.ptpAmount) || 0;
      if (curr.status === 'COLLECTED') {
        acc[process].collected += Number(curr.ptpAmount) || 0;
      } else {
        acc[process].pending += Number(curr.ptpAmount) || 0;
      }
      return acc;
    }, {});

    // Status-wise collection
    const statusCollection = records.reduce((acc: any, curr) => {
      const status = curr.status || 'Pending';
      if (!acc[status]) {
        acc[status] = {
          totalAmount: 0,
          count: 0,
        };
      }
      acc[status].count += 1;
      acc[status].totalAmount += Number(curr.ptpAmount) || 0;
      return acc;
    }, {});

    // Date-wise collection
    const dateCollection = records.reduce((acc: any, curr) => {
      const date = curr.paymentDate ? curr.paymentDate.split('T')[0] : 'Unscheduled';
      if (!acc[date]) {
        acc[date] = {
          totalAmount: 0,
          count: 0,
          collected: 0,
          pending: 0,
        };
      }
      acc[date].count += 1;
      acc[date].totalAmount += Number(curr.ptpAmount) || 0;
      if (curr.status === 'COLLECTED') {
        acc[date].collected += Number(curr.ptpAmount) || 0;
      } else {
        acc[date].pending += Number(curr.ptpAmount) || 0;
      }
      return acc;
    }, {});

    return {
      processCollection,
      statusCollection,
      dateCollection,
    };
  };

  const renderCollectionReport = () => {
    const report = generateCollectionReport();
    
    const downloadReport = async (exportFormat: 'csv' | 'excel') => {
      try {
        // Prepare data for export
        const processData = Object.entries(report.processCollection).map(([process, data]: [string, any]) => ({
          'Process': process,
          'Total Cases': data.count,
          'Total Amount': data.totalAmount,
          'Collected': data.collected,
          'Pending': data.pending,
          'Collection %': data.totalAmount ? ((data.collected / data.totalAmount) * 100).toFixed(2) : 0
        }));

        const statusData = Object.entries(report.statusCollection).map(([status, data]: [string, any]) => ({
          'Status': status,
          'Total Cases': data.count,
          'Total Amount': data.totalAmount,
          '% of Total': ((data.totalAmount / Object.values(report.statusCollection).reduce((sum: number, curr: any) => 
            sum + curr.totalAmount, 0)) * 100).toFixed(2)
        }));

        const dateData = Object.entries(report.dateCollection)
          .sort(([dateA], [dateB]) => dateA.localeCompare(dateB))
          .map(([date, data]: [string, any]) => ({
            'Date': date,
            'Total Cases': data.count,
            'Total Amount': data.totalAmount,
            'Collected': data.collected,
            'Pending': data.pending,
            'Collection %': data.totalAmount ? ((data.collected / data.totalAmount) * 100).toFixed(2) : 0
          }));

        const currentDate = new Date();
        const fileName = `CRM_Report_${format(currentDate, 'yyyy-MM-dd')}`;

        if (exportFormat === 'excel') {
          const wb = XLSX.utils.book_new();
          
          // Process-wise sheet
          const ws1 = XLSX.utils.json_to_sheet(processData);
          XLSX.utils.book_append_sheet(wb, ws1, "Process-wise Collection");
          
          // Status-wise sheet
          const ws2 = XLSX.utils.json_to_sheet(statusData);
          XLSX.utils.book_append_sheet(wb, ws2, "Status-wise Collection");
          
          // Date-wise sheet
          const ws3 = XLSX.utils.json_to_sheet(dateData);
          XLSX.utils.book_append_sheet(wb, ws3, "Date-wise Collection");
          
          // Generate Excel file
          const excelBuffer = XLSX.write(wb, { bookType: 'xlsx', type: 'array' });
          const data = new Blob([excelBuffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });

          // Create a file input element
          const fileInput = document.createElement('input');
          fileInput.type = 'file';
          fileInput.accept = '.xlsx';
          fileInput.style.display = 'none';
          document.body.appendChild(fileInput);

          // Create a download link
          const downloadLink = document.createElement('a');
          downloadLink.href = URL.createObjectURL(data);
          downloadLink.download = `${fileName}.xlsx`;
          
          // Trigger the file save dialog
          if (window.showSaveFilePicker) {
            try {
              const handle = await window.showSaveFilePicker({
                suggestedName: `${fileName}.xlsx`,
                types: [{
                  description: 'Excel Files',
                  accept: {
                    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': ['.xlsx']
                  }
                }]
              });
              const writable = await handle.createWritable();
              await writable.write(data);
              await writable.close();
            } catch (err) {
              // Fallback to regular download if user cancels or browser doesn't support the API
              downloadLink.click();
            }
          } else {
            // Fallback for browsers that don't support showSaveFilePicker
            downloadLink.click();
          }

          // Cleanup
          URL.revokeObjectURL(downloadLink.href);
          document.body.removeChild(fileInput);
        } else {
          // CSV format - combine all data with headers
          const csvContent = [
            "Process-wise Collection",
            Object.keys(processData[0]).join(','),
            ...processData.map(row => Object.values(row).join(',')),
            "",
            "Status-wise Collection",
            Object.keys(statusData[0]).join(','),
            ...statusData.map(row => Object.values(row).join(',')),
            "",
            "Date-wise Collection",
            Object.keys(dateData[0]).join(','),
            ...dateData.map(row => Object.values(row).join(','))
          ].join('\n');

          const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });

          // Create a download link
          const downloadLink = document.createElement('a');
          downloadLink.href = URL.createObjectURL(blob);
          downloadLink.download = `${fileName}.csv`;

          // Trigger the file save dialog
          if (window.showSaveFilePicker) {
            try {
              const handle = await window.showSaveFilePicker({
                suggestedName: `${fileName}.csv`,
                types: [{
                  description: 'CSV Files',
                  accept: {
                    'text/csv': ['.csv']
                  }
                }]
              });
              const writable = await handle.createWritable();
              await writable.write(blob);
              await writable.close();
            } catch (err) {
              // Fallback to regular download if user cancels or browser doesn't support the API
              downloadLink.click();
            }
          } else {
            // Fallback for browsers that don't support showSaveFilePicker
            downloadLink.click();
          }

          // Cleanup
          URL.revokeObjectURL(downloadLink.href);
        }
      } catch (error) {
        console.error('Error downloading report:', error);
        // You might want to show an error message to the user here
      }
    };
    
    return (
      <Box sx={{ mt: 4 }}>
        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
          <Typography variant="h6">Total Collection Report</Typography>
          <ButtonGroup variant="contained" size="small">
            <Button
              startIcon={<DownloadIcon />}
              onClick={() => downloadReport('csv')}
              title="Download as CSV file"
            >
              CSV
            </Button>
            <Button
              startIcon={<DownloadIcon />}
              onClick={() => downloadReport('excel')}
              title="Download as Excel file"
            >
              Excel
            </Button>
          </ButtonGroup>
        </Box>
        
        {/* Process-wise Collection */}
        <Paper sx={{ p: 2, mb: 3 }}>
          <Typography variant="subtitle1" gutterBottom>Process-wise Collection</Typography>
          <TableContainer>
            <Table size="small">
              <TableHead>
                <TableRow>
                  <TableCell>Process</TableCell>
                  <TableCell align="right">Total Cases</TableCell>
                  <TableCell align="right">Total Amount</TableCell>
                  <TableCell align="right">Collected</TableCell>
                  <TableCell align="right">Pending</TableCell>
                  <TableCell align="right">Collection %</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {Object.entries(report.processCollection).map(([process, data]: [string, any]) => (
                  <TableRow key={process}>
                    <TableCell>{process}</TableCell>
                    <TableCell align="right">{data.count}</TableCell>
                    <TableCell align="right">₹{data.totalAmount.toLocaleString()}</TableCell>
                    <TableCell align="right">₹{data.collected.toLocaleString()}</TableCell>
                    <TableCell align="right">₹{data.pending.toLocaleString()}</TableCell>
                    <TableCell align="right">
                      {data.totalAmount ? ((data.collected / data.totalAmount) * 100).toFixed(2) : 0}%
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
        </Paper>

        {/* Status-wise Collection */}
        <Paper sx={{ p: 2, mb: 3 }}>
          <Typography variant="subtitle1" gutterBottom>Status-wise Collection</Typography>
          <TableContainer>
            <Table size="small">
              <TableHead>
                <TableRow>
                  <TableCell>Status</TableCell>
                  <TableCell align="right">Total Cases</TableCell>
                  <TableCell align="right">Total Amount</TableCell>
                  <TableCell align="right">% of Total</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {Object.entries(report.statusCollection).map(([status, data]: [string, any]) => (
                  <TableRow key={status}>
                    <TableCell>{status}</TableCell>
                    <TableCell align="right">{data.count}</TableCell>
                    <TableCell align="right">₹{data.totalAmount.toLocaleString()}</TableCell>
                    <TableCell align="right">
                      {((data.totalAmount / Object.values(report.statusCollection).reduce((sum: number, curr: any) => 
                        sum + curr.totalAmount, 0)) * 100).toFixed(2)}%
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
        </Paper>

        {/* Date-wise Collection */}
        <Paper sx={{ p: 2 }}>
          <Typography variant="subtitle1" gutterBottom>Date-wise Collection</Typography>
          <TableContainer>
            <Table size="small">
              <TableHead>
                <TableRow>
                  <TableCell>Date</TableCell>
                  <TableCell align="right">Total Cases</TableCell>
                  <TableCell align="right">Total Amount</TableCell>
                  <TableCell align="right">Collected</TableCell>
                  <TableCell align="right">Pending</TableCell>
                  <TableCell align="right">Collection %</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {Object.entries(report.dateCollection)
                  .sort(([dateA], [dateB]) => dateA.localeCompare(dateB))
                  .map(([date, data]: [string, any]) => (
                    <TableRow key={date}>
                      <TableCell>{date}</TableCell>
                      <TableCell align="right">{data.count}</TableCell>
                      <TableCell align="right">₹{data.totalAmount.toLocaleString()}</TableCell>
                      <TableCell align="right">₹{data.collected.toLocaleString()}</TableCell>
                      <TableCell align="right">₹{data.pending.toLocaleString()}</TableCell>
                      <TableCell align="right">
                        {data.totalAmount ? ((data.collected / data.totalAmount) * 100).toFixed(2) : 0}%
                      </TableCell>
                    </TableRow>
                  ))}
              </TableBody>
            </Table>
          </TableContainer>
        </Paper>
      </Box>
    );
  };

  const renderReportsContent = () => {
    return (
      <Paper sx={{ p: 3 }}>
        <Box sx={{ mb: 3 }}>
          <Typography variant="h6" gutterBottom>Reports Dashboard</Typography>
          <Grid container spacing={2} alignItems="center">
            <Grid item>
              <ToggleButtonGroup
                value={chartType}
                exclusive
                onChange={(_, value) => value && setChartType(value)}
                size="small"
              >
                <ToggleButton value="process">Process-wise</ToggleButton>
                <ToggleButton value="status">Status-wise</ToggleButton>
                <ToggleButton value="date">Date-wise</ToggleButton>
              </ToggleButtonGroup>
            </Grid>
            <Grid item>
              <ToggleButtonGroup
                value={chartView}
                exclusive
                onChange={(_, value) => value && setChartView(value)}
                size="small"
              >
                <ToggleButton value="bar">Bar Chart</ToggleButton>
                <ToggleButton value="pie">Pie Chart</ToggleButton>
                <ToggleButton value="line">Line Chart</ToggleButton>
              </ToggleButtonGroup>
            </Grid>
          </Grid>
        </Box>
        <Box sx={{ display: 'flex', justifyContent: 'center', overflow: 'auto' }}>
          {renderChart()}
        </Box>
        {renderCollectionReport()}
      </Paper>
    );
  };

  const renderContent = () => {
    switch (selectedMenu) {
      case 'Payment Tracker':
        return (
          <>
            <Paper sx={{ p: 3, mb: 3 }}>
              <Typography variant="h6" gutterBottom>
                Add New Record
              </Typography>
              <form onSubmit={handleSubmit}>
                <Grid container spacing={2}>
                  <Grid item xs={12} sm={6} md={4}>
                    <TextField
                      required
                      fullWidth
                      label="Account Number"
                      name="accountNumber"
                      value={formData.accountNumber || ''}
                      onChange={handleInputChange}
                    />
                  </Grid>
                  <Grid item xs={12} sm={6} md={4}>
                    <TextField
                      required
                      fullWidth
                      label="Customer Name"
                      name="customerName"
                      value={formData.customerName || ''}
                      onChange={handleInputChange}
                    />
                  </Grid>
                  <Grid item xs={12} sm={6} md={4}>
                    <TextField
                      required
                      fullWidth
                      label="PTP Amount"
                      name="ptpAmount"
                      type="number"
                      value={formData.ptpAmount || ''}
                      onChange={handleInputChange}
                    />
                  </Grid>
                  <Grid item xs={12} sm={6} md={4}>
                    <FormControl fullWidth required>
                      <InputLabel>Status</InputLabel>
                      <Select
                        name="status"
                        value={formData.status || ''}
                        label="Status"
                        onChange={handleSelectChange}
                      >
                        {statusOptions.map((option) => (
                          <MenuItem key={option} value={option}>
                            {option}
                          </MenuItem>
                        ))}
                      </Select>
                    </FormControl>
                  </Grid>
                  <Grid item xs={12} sm={6} md={4}>
                    <TextField
                      fullWidth
                      label="Payment Date"
                      name="paymentDate"
                      type="date"
                      value={formData.paymentDate || ''}
                      onChange={handleInputChange}
                      InputLabelProps={{ shrink: true }}
                    />
                  </Grid>
                  <Grid item xs={12} sm={6} md={4}>
                    <TextField
                      required
                      fullWidth
                      label="Contact Number"
                      name="contactNumber"
                      value={formData.contactNumber || ''}
                      onChange={handleInputChange}
                    />
                  </Grid>
                  <Grid item xs={12} sm={6} md={4}>
                    <TextField
                      required
                      fullWidth
                      label="Caller Name"
                      name="callerName"
                      value={formData.callerName || ''}
                      onChange={handleInputChange}
                    />
                  </Grid>
                  <Grid item xs={12} sm={6} md={4}>
                    <TextField
                      required
                      fullWidth
                      label="AM & TL"
                      name="amAndTl"
                      value={formData.amAndTl || ''}
                      onChange={handleInputChange}
                    />
                  </Grid>
                  <Grid item xs={12} sm={6} md={4}>
                    <FormControl fullWidth required>
                      <InputLabel>Process</InputLabel>
                      <Select
                        name="process"
                        value={formData.process || ''}
                        label="Process"
                        onChange={handleSelectChange}
                      >
                        {processOptions.map((option) => (
                          <MenuItem key={option} value={option}>
                            {option}
                          </MenuItem>
                        ))}
                      </Select>
                    </FormControl>
                  </Grid>
                  <Grid item xs={12}>
                    <Box sx={{ display: 'flex', justifyContent: 'flex-end', mt: 2 }}>
                      <Button
                        type="submit"
                        variant="contained"
                        color="primary"
                        size="large"
                      >
                        Add Record
                      </Button>
                    </Box>
                  </Grid>
                </Grid>
              </form>
            </Paper>

            <Paper sx={{ height: 600, width: '100%' }}>
              <DataGrid
                rows={records}
                columns={columns}
                initialState={{
                  pagination: {
                    paginationModel: { pageSize: 10, page: 0 },
                  },
                }}
                pageSizeOptions={[10, 25, 50]}
                disableRowSelectionOnClick
                autoHeight
              />
            </Paper>
          </>
        );
      case 'Static Data':
        return renderStaticDataContent();
      case 'Reports':
        return renderReportsContent();
      default:
        return null;
    }
  };

  return (
    <ThemeProvider theme={theme}>
      <Box sx={{ display: 'flex' }}>
        <CssBaseline />
        <AppBar
          position="fixed"
          sx={{
            width: { sm: `calc(100% - ${drawerWidth}px)` },
            ml: { sm: `${drawerWidth}px` },
          }}
        >
          <Toolbar>
            <IconButton
              color="inherit"
              aria-label="open drawer"
              edge="start"
              onClick={handleDrawerToggle}
              sx={{ mr: 2, display: { sm: 'none' } }}
            >
              <MenuIcon />
            </IconButton>
            <Typography variant="h6" noWrap component="div">
              CRM System
            </Typography>
          </Toolbar>
        </AppBar>
        <Box
          component="nav"
          sx={{ width: { sm: drawerWidth }, flexShrink: { sm: 0 } }}
        >
          <Drawer
            variant="temporary"
            open={mobileOpen}
            onClose={handleDrawerToggle}
            ModalProps={{
              keepMounted: true, // Better open performance on mobile.
            }}
            sx={{
              display: { xs: 'block', sm: 'none' },
              '& .MuiDrawer-paper': { boxSizing: 'border-box', width: drawerWidth },
            }}
          >
            {drawer}
          </Drawer>
          <Drawer
            variant="permanent"
            sx={{
              display: { xs: 'none', sm: 'block' },
              '& .MuiDrawer-paper': { boxSizing: 'border-box', width: drawerWidth },
            }}
            open
          >
            {drawer}
          </Drawer>
        </Box>
        <Box
          component="main"
          sx={{
            flexGrow: 1,
            p: 3,
            width: { sm: `calc(100% - ${drawerWidth}px)` },
            marginTop: '64px',
          }}
        >
          {error && (
            <Paper sx={{ p: 2, mb: 2, bgcolor: 'error.light', color: 'error.contrastText' }}>
              <Typography>Error: {error}</Typography>
            </Paper>
          )}

          {loading ? (
            <Paper sx={{ p: 3, mb: 3, textAlign: 'center' }}>
              <Typography>Loading data...</Typography>
            </Paper>
          ) : (
            renderContent()
          )}
        </Box>
      </Box>
    </ThemeProvider>
  );
};

export default App; 